const edit = $('Doctor edit rate (30d)').first().json;
const lat = $('Latency (30d)').first().json;
const counts = $('Pipeline counters').first().json;
const editRate = edit.proposed > 0 ? edit.changed / edit.proposed : 0;
const snapshot = {
  doctorEditRate: editRate, doctorEditRateSampleSize: edit.sample_size, doctorEditRateBreach: editRate > 0.20,
  latencyMedianHours: Number(lat.median_hours ?? 0), latencyP90Hours: Number(lat.p90_hours ?? 0), latencyBreach: Number(lat.median_hours ?? 0) > 24,
  claimsProcessed30d: counts.claims_processed_30d, pendingDoctorReviews: counts.pending_doctor_reviews,
  regenerationCount30d: counts.regeneration_count_30d, validationFailures30d: counts.validation_failures_30d,
  slaApproaching: counts.sla_approaching, reconciliationDiscrepancies: counts.reconciliation_discrepancies,
  generatedAt: new Date().toISOString(),
  // Denial rate needs a payer remittance feed this pipeline doesn't have yet; left for that integration, not estimated here.
  denialRateCurrent: null, denialRateBaseline: null, denialRateNote: 'requires payer remittance/835 feed — not yet integrated',
};
return [{ json: { events: [{ type: 'kpi.updated', kpi: snapshot }] } }];
